@@ -0,0 +1,36 @@
+import express, { Request, Response } from "express";
+import { getReadyJobs, markNotified } from "./jobs.ts";
+
+const app = express();
+app.use(express.json());
+
+const API_KEY = process.env.NOTIFICATIONS_API_KEY || "default-key";
+
+const authenticate = (req: Request, res: Response, next: () => void) => {
+  const key = req.headers["x-api-key"];
+  if (key !== API_KEY) {
+    res.status(401).json({ error: "Unauthorized" });
+    return;
+  }
+  next();
+};
+
+app.use(authenticate);
+
+app.get("/api/jobs/ready", async (req: Request, res: Response) => {
+  const limit = parseInt(req.query.limit as string) || 10;
+  const jobs = await getReadyJobs(limit);
+  res.json(jobs);
+});
+
+app.post("/api/jobs/:id/complete", async (req: Request, res: Response) => {
+  const { id } = req.params;
+  await markNotified(id);
+  res.json({ success: true });
+});
+
+export const runServer = (port: number = 3000): void => {
+  app.listen(port, () => {
+    console.log(`Notifications API running on port ${port}`);
+  });
+};
