+
+export const getReadyJobs = async (limit: number = 10): Promise<Job[]> => {
+  const result = await pool.query(
+    "SELECT id, payload FROM jobs WHERE status = 'ready' ORDER BY created_at LIMIT $1",
+    [limit],
+  );
+  return result.rows;
+};
+
+export const markNotified = async (id: string): Promise<void> => {
+  await pool.query("UPDATE jobs SET status = 'notified' WHERE id = $1", [id]);
+};
